"""Resume sorting using measured poses, not the nominal placement bounds."""

import inspect
import math
import statistics


def _motion_adapter(api):
    """Accommodate common Cartesian-motion API signatures."""
    for name in ("move_to", "move_tcp", "movel", "move", "set_tcp_pose"):
        method = getattr(api, name, None)
        if callable(method):
            break
    else:
        raise RuntimeError("No Cartesian motion method is available.")

    try:
        signature = inspect.signature(method)
    except (TypeError, ValueError):
        signature = None

    def move(x, y, z):
        xyz = [float(x), float(y), float(z)]
        if signature is None:
            return method(*xyz)

        args, kwargs = [], {}
        supplied_position = False

        for parameter in signature.parameters.values():
            key = parameter.name.lower()
            if key in ("self", "cls"):
                continue
            if parameter.kind == inspect.Parameter.VAR_POSITIONAL:
                if not supplied_position:
                    args.extend(xyz)
                    supplied_position = True
                continue
            if parameter.kind == inspect.Parameter.VAR_KEYWORD:
                continue

            if key in ("x", "y", "z"):
                value = xyz[("x", "y", "z").index(key)]
                supplied_position = True
            elif key in ("position", "pos", "xyz", "target", "tcp",
                         "target_position", "tcp_position", "pose"):
                value = xyz
                supplied_position = True
            elif parameter.default is not inspect.Parameter.empty:
                # Preserve the configured downward tool orientation.
                continue
            elif key in ("yaw", "theta"):
                value = 0.0
            else:
                raise RuntimeError(
                    "Unsupported required motion parameter: "
                    + parameter.name
                )

            if parameter.kind == inspect.Parameter.POSITIONAL_ONLY:
                args.append(value)
            else:
                kwargs[parameter.name] = value

        if not supplied_position:
            kwargs.update(zip(("x", "y", "z"), xyz))
        return method(*args, **kwargs)

    return move


def _observe(api, samples=5):
    observations = [api.cube_pose() for _ in range(samples)]
    position = [
        statistics.median(item[0][axis] for item in observations)
        for axis in range(3)
    ]
    colour = max(
        ("red", "green", "blue"),
        key=lambda candidate: sum(item[2] == candidate
                                  for item in observations),
    )
    if not all(math.isfinite(value) for value in position):
        raise RuntimeError("Invalid measured cube position.")
    return position, colour


def _settled_done(api):
    # Simulator queries also allow its success predicate to be updated.
    for _ in range(20):
        if api.done():
            return True
    return False


def run(api):
    if api.done():
        return

    move = _motion_adapter(api)
    clearance = 0.20

    # The trace shows an empty cup. Do not reset the simulator or reject the
    # consistently observed cube merely because it is outside the test range.
    api.suction(on=False)

    for _ in range(3):
        cube, colour = _observe(api, samples=9)
        bin_position, _ = api.bin_pose(colour=colour)
        bx, by = bin_position[:2]

        attached = False

        # Pose APIs differ on whether cube z denotes its centre or top.
        # Approach the higher possibilities first and verify each grasp by
        # an actual lift, rather than interpreting suction-on as attachment.
        for height_offset in (0.04, 0.02, 0.0):
            cube, colour = _observe(api)
            cx, cy, cz = cube

            api.suction(on=False)
            move(cx, cy, clearance)
            move(cx, cy, cz + 0.065)
            move(cx, cy, cz + height_offset)
            api.suction(on=True)

            move(cx, cy, clearance)
            lifted, lifted_colour = _observe(api, samples=3)

            if (
                lifted[2] > cz + 0.025
                and math.hypot(lifted[0] - cx, lifted[1] - cy) < 0.045
            ):
                attached = True
                colour = lifted_colour
                break

            api.suction(on=False)

        if not attached:
            continue

        bin_position, _ = api.bin_pose(colour=colour)
        bx, by = bin_position[:2]

        # Carry above the 60 mm walls. A centred 40 mm cube fits the
        # 120 mm opening at every yaw, so wrist rotation is unnecessary.
        move(bx, by, clearance)
        move(bx, by, 0.105)
        api.suction(on=False)
        move(bx, by, clearance)

        if _settled_done(api):
            return

    api.suction(on=False)
    if not _settled_done(api):
        raise RuntimeError("Recovery attempts exhausted; sorting not confirmed.")
