import inspect
import math
from statistics import median


def _make_mover(api):
    """Adapt to the available Cartesian-motion signature."""
    names = (
        "move_to", "move_tcp", "movel", "move_linear",
        "move_cartesian", "move", "set_tcp_pose",
    )

    def value(name, x, y, z):
        name = name.lower()
        if name in ("x", "x_m"):
            return x
        if name in ("y", "y_m"):
            return y
        if name in ("z", "z_m"):
            return z
        if name in ("position", "pos", "xyz", "target_position", "target_xyz"):
            return [x, y, z]
        if name in ("pose", "tcp_pose", "target_pose"):
            return [x, y, z, math.pi, 0.0, 0.0]
        if name in ("yaw_deg", "pitch_deg"):
            return 0.0
        if name == "roll_deg":
            return 180.0
        if name in ("yaw", "yaw_rad", "pitch", "pitch_rad", "ry", "rz"):
            return 0.0
        if name in ("roll", "roll_rad", "rx"):
            return math.pi
        if name in ("rpy", "orientation", "rotation", "rotvec"):
            return [math.pi, 0.0, 0.0]
        if name in ("rpy_deg", "orientation_deg"):
            return [180.0, 0.0, 0.0]
        if name in ("quaternion", "quat"):
            return [1.0, 0.0, 0.0, 0.0]
        if name in ("speed", "velocity", "v", "speed_m_s"):
            return 0.10
        if name in ("acceleration", "accel", "a"):
            return 0.25
        if name in ("blocking", "wait"):
            return True
        if name in ("duration", "duration_s"):
            return 1.0
        raise KeyError(name)

    for name in names:
        fn = getattr(api, name, None)
        if not callable(fn):
            continue
        try:
            parameters = list(inspect.signature(fn).parameters.values())
        except (TypeError, ValueError):
            continue

        explicit = [
            p for p in parameters
            if p.kind not in (p.VAR_POSITIONAL, p.VAR_KEYWORD)
        ]
        if not explicit:
            continue

        position_names = {
            "x", "x_m", "position", "pos", "xyz",
            "target_position", "target_xyz", "pose", "tcp_pose", "target_pose",
        }
        if not any(p.name.lower() in position_names for p in explicit):
            continue

        try:
            for p in explicit:
                if p.default is p.empty:
                    value(p.name, 0.45, -0.05, 0.15)
        except KeyError:
            continue

        def move(x, y, z, _fn=fn, _parameters=explicit):
            args, kwargs = [], {}
            for p in _parameters:
                try:
                    v = value(p.name, x, y, z)
                except KeyError:
                    if p.kind == p.POSITIONAL_ONLY:
                        args.append(p.default)
                    continue
                if p.kind == p.POSITIONAL_ONLY:
                    args.append(v)
                else:
                    kwargs[p.name] = v
            result = _fn(*args, **kwargs)
            if result is False:
                raise RuntimeError("Cartesian motion was rejected.")
            return result

        return move

    raise RuntimeError("No supported Cartesian-motion interface was found.")


def run(api):
    if api.done():
        return

    move = _make_mover(api)

    # Continue the existing trial: the last recorded state has suction off.
    api.suction(on=False)

    readings = [api.cube_pose() for _ in range(5)]
    colours = [r[2] for r in readings]
    colour = max(set(colours), key=colours.count)
    if colour not in ("red", "green", "blue"):
        raise RuntimeError("Unrecognised cube colour.")

    observed_x = median(r[0][0] for r in readings)
    observed_y = median(r[0][1] for r in readings)
    observed_z = median(r[0][2] for r in readings)

    bin_position, _ = api.bin_pose(colour=colour)
    bx, by = bin_position[:2]

    travel_z = 0.16
    # The recorded cube height is approximately its 40 mm top surface.
    contact_z = 0.039
    release_z = 0.045

    candidates = []

    def add_candidate(x, y):
        if not any(abs(x - px) < 0.001 and abs(y - py) < 0.001
                   for px, py in candidates):
            candidates.append((x, y))

    # The repeated reported XY positions contradict the specified placement
    # envelope. Averaging cannot remove a systematic perception offset.
    in_envelope = (
        0.40 <= observed_x <= 0.50 and
        -0.10 <= observed_y <= 0.00
    )
    if in_envelope:
        add_candidate(observed_x, observed_y)

    add_candidate(0.45, -0.05)
    grid = [
        (0.40 + i * 0.0125, -0.10 + j * 0.0125)
        for i in range(9)
        for j in range(9)
    ]
    grid.sort(key=lambda p: (p[0] - 0.45) ** 2 + (p[1] + 0.05) ** 2)
    for point in grid:
        add_candidate(*point)

    # If this trial actually violates its nominal placement specification,
    # retain a small, bounded search around the observed position as fallback.
    if not in_envelope:
        for dx, dy in (
            (0, 0), (-0.01, 0), (0.01, 0), (0, -0.01), (0, 0.01),
            (-0.01, -0.01), (-0.01, 0.01),
            (0.01, -0.01), (0.01, 0.01),
        ):
            x, y = observed_x + dx, observed_y + dy
            if 0.30 <= x <= 0.78 and -0.20 <= y <= 0.10:
                add_candidate(x, y)

    current_x, current_y = 0.45, -0.05

    for x, y in candidates:
        if api.done():
            return

        # All horizontal transport occurs with the cube bottom above the rim.
        move(current_x, current_y, travel_z)
        move(x, y, travel_z)
        move(x, y, 0.060)
        move(x, y, contact_z)

        suction_result = api.suction(on=True)
        move(x, y, travel_z)
        current_x, current_y = x, y

        lifted_readings = [api.cube_pose() for _ in range(3)]
        lifted_z = median(r[0][2] for r in lifted_readings)
        height_confirms_pick = lifted_z > observed_z + 0.060

        # Some APIs return attachment state; others only acknowledge vacuum.
        # An acknowledgement therefore permits a placement attempt, but never
        # counts as task success.
        possible_pick = height_confirms_pick or bool(suction_result)

        if not possible_pick:
            api.suction(on=False)
            continue

        # Yaw alignment is unnecessary: even a diagonally oriented 40 mm
        # cube fits comfortably inside a 120 mm bin.
        move(bx, by, travel_z)
        move(bx, by, release_z)
        api.suction(on=False)
        move(bx, by, travel_z)
        current_x, current_y = bx, by

        for _ in range(5):
            if api.done():
                return
            api.cube_pose()  # Allow settling without changing the grasp state.

    api.suction(on=False)
    if not api.done():
        raise RuntimeError("Bounded recovery search exhausted; sorting is unconfirmed.")
